PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
PRAGMA locking_mode=EXCLUSIVE;
CREATE TABLE IF NOT EXISTS meta(version INTEGER NOT NULL, epoch INTEGER NOT NULL);
INSERT INTO meta SELECT 1,0 WHERE NOT EXISTS(SELECT 1 FROM meta);
CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY, parent INTEGER REFERENCES tasks(id), goal TEXT NOT NULL, state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id INTEGER PRIMARY KEY, scope INTEGER NOT NULL REFERENCES tasks(id), purpose TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS segments(id INTEGER PRIMARY KEY, session INTEGER NOT NULL UNIQUE REFERENCES sessions(id), harness TEXT NOT NULL, binding TEXT NOT NULL, native_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runs(id INTEGER PRIMARY KEY, segment INTEGER NOT NULL REFERENCES segments(id), epoch INTEGER NOT NULL, state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY, task INTEGER NOT NULL REFERENCES tasks(id), sender INTEGER NOT NULL REFERENCES sessions(id), target INTEGER NOT NULL REFERENCES sessions(id), kind TEXT NOT NULL, reply_to INTEGER REFERENCES messages(id), key TEXT NOT NULL, body TEXT NOT NULL, deadline INTEGER NOT NULL, state TEXT NOT NULL, UNIQUE(sender,key));
CREATE TABLE IF NOT EXISTS attempts(id INTEGER PRIMARY KEY, message INTEGER NOT NULL REFERENCES messages(id), segment INTEGER NOT NULL REFERENCES segments(id), run INTEGER NOT NULL REFERENCES runs(id), slot TEXT NOT NULL, account TEXT NOT NULL, model TEXT NOT NULL, provider TEXT NOT NULL, protocol TEXT NOT NULL, state TEXT NOT NULL, simulated INTEGER NOT NULL CHECK(simulated=1));
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY, message INTEGER REFERENCES messages(id), event TEXT NOT NULL, simulated INTEGER NOT NULL CHECK(simulated=1));
